-- Add every bullet fact from the supplied seventh Lily collection. Russian/Russia
-- content is soft-hidden with isActive rather than deleted, preserving data
-- and historical delivery records for a future editorial re-enable.
WITH supplied_facts (ordinal, text) AS (
VALUES
  (579, $$Пассивный словарный запас: Чтение переводит редкие, архаичные и сложные слова из пассивного багажа в активную повседневную речь.$$),
  (580, $$Чувство языка: Литература развивает интуитивное понимание языковых норм: человек начинает чувствовать, где допущена стилистическая ошибка, даже не зная правил.$$),
  (581, $$Избавление от слов-паразитов: Начитанный человек реже использует в речи «э-э», «как бы», «ну» и «короче», так как его мозг быстрее подбирает точные синонимы.$$),
  (582, $$Метафоричность мышления: Книги учат говорить образно, использовать яркие сравнения и аллегории, что делает речь убедительной и живой.$$),
  (583, $$Формулирование мыслей: Чтение приучает мозг к сложным синтаксическим конструкциям, помогая четко и емко выражать абстрактные или запутанные идеи.$$),
  (584, $$Грамотность на автомате: Зрительная память фиксирует правильное написание слов и расстановку знаков препинания, развивая так называемую «врожденную грамотность».$$),
  (585, $$Ораторские навыки: Изучение диалогов и монологов великих персонажей учит держать паузу, выстраивать драматургию речи и удерживать внимание публики.$$),
  (586, $$Разнообразие интонаций: Чтение литературы с богатой эмоциональной палитрой развивает гибкость голоса и умение передавать оттенки смыслов интонацией.$$),
  (587, $$Умение вести дискуссию: Литературные споры героев дают читателю готовые паттерны ведения аргументированного и интеллигентного диалога.$$),
  (588, $$Красота слога: Начитанность формирует индивидуальный, узнаваемый стиль письма и устной речи, выделяющий человека из толпы.$$),
  (589, $$Анализ скрытых мотивов: Литература учит видеть подтекст, читать «между строк» и понимать истинные причины поступков людей, скрытые за их словами.$$),
  (590, $$Причинно-следственные связи: Многослойные сюжеты развивают способность просчитывать последствия действий на много шагов вперед.$$),
  (591, $$Дедукция и индукция: Чтение детективов и интеллектуальных романов тренирует мозг собирать общую картину из разрозненных улик и деталей.$$),
  (592, $$Критическое восприятие информации: Книги показывают одну и ту же ситуацию глазами разных персонажей, избавляя от привычки верить первому встречному мнению.$$),
  (593, $$Умение распознавать манипуляции: Анализируя поведение книжных злодеев и интриганов, человек учится вовремя замечать психологическое давление в реальной жизни.$$),
  (594, $$Концентрация и фокус: Чтение длинного романа требует удержания внимания на одном объекте часами, что лечит «клиповое мышление» соцсетей.$$),
  (595, $$Оперативная память: Чтобы понимать сюжет, мозг вынужден держать в уме десятки имен, родственных связей, локаций и деталей прошлого героев.$$),
  (596, $$Гибкость ума: Знакомство со сложными философскими и концептуальными романами учит мозг быстро переключаться между разными моделями реальности.$$),
  (597, $$Распознавание паттернов: Литература структурирует хаос: человек начинает видеть в реальной жизни те же сюжетные архетипы, что описаны в классике.$$),
  (598, $$Скорость принятия решений: Натренированный книжными дилеммами мозг быстрее обрабатывает информацию и находит выходы из кризисных ситуаций.$$),
  (599, $$Теория разума (Theory of Mind): Литература развивает способность понимать, что у других людей есть свои, отличные от ваших, убеждения, знания и желания.$$),
  (600, $$Проживание чужого опыта: Книга позволяет примерить на себя жизнь человека другой эпохи, расы, пола или социального статуса, расширяя границы эго.$$),
  (601, $$Эмоциональный словарь: Литература помогает идентифицировать и назвать тончайшие оттенки собственных чувств (тоска, меланхолия, тщеславие, благородство).$$),
  (602, $$Снижение эгоцентризма: Понимая внутреннюю боль и мысли персонажей, человек осознает, что мир не вращается исключительно вокруг него.$$),
  (603, $$Развитие сострадания: Описание трагедий и драм в книгах делает человека более чутким и отзывчивым к реальным страданиям окружающих.$$),
  (604, $$Терпимость к недостаткам: Классика показывает, что идеальных людей нет, помогая принимать слабости — как свои собственные, так и чужие.$$),
  (605, $$Управление гневом: Переживая катарсис вместе с героями, читатель экологично выплескивает накопившуюся агрессию и внутреннее напряжение.$$),
  (606, $$Интуитивное понимание людей: Начитанность дает колоссальную базу психологических портретов, что позволяет с первых минут считывать характер реального собеседника.$$),
  (607, $$Укрепление близких связей: Способность глубоко сопереживать, развитая книгами, помогает выстраивать доверительные отношения в семье и браке.$$),
  (608, $$Психологическая зрелость: Литература ускоряет эмоциональное взросление, помогая пережить подростковые кризисы и юношеский максимализм.$$),
  (609, $$Визуализация без костылей: В отличие от кино, где картинка готова, книга заставляет мозг самостоятельно режиссировать сцены, рисовать лица и пейзажи.$$),
  (610, $$Ассоциативное мышление: Литературные метафоры связывают между собой далекие понятия, помогая генерировать оригинальные идеи в науке и бизнесе.$$),
  (611, $$Генерация альтернатив: Чтение фантастики и утопий развивает навык мыслить в категории «А что, если?», создавая новые концепты из ничего.$$),
  (612, $$Художественный вкус: Знакомство с великими описаниями природы, архитектуры и интерьеров формирует внутреннее чувство гармонии и эстетики.$$),
  (613, $$Преодоление шаблонов: Литература ломает банальные штампы мышления, предлагая парадоксальные взгляды на привычные вещи.$$),
  (614, $$Пространственное воображение: Следя за перемещениями героев по вымышленным мирам или старинным городам, мозг строит сложные ментальные 3D-карты.$$),
  (615, $$Творческая смелость: Примеры писателей-новаторов (Джойса, Кафки, Маяковского) вдохновляют человека не бояться самовыражения в своей профессии.$$),
  (616, $$Юмор и остроумие: Качественная сатира и ирония в литературе развивают тонкое чувство юмора, помогая находить смешное в сложных ситуациях.$$),
  (617, $$Интеллектуальное любопытство: Хорошая книга всегда оставляет вопросы, стимулируя человека изучать историю, искусство, философию или физику.$$),
  (618, $$Синтез идей: Начитанность позволяет соединять мысли авторов разных эпох, создавая уникальные творческие проекты на стыке культур.$$),
  (619, $$Историческая эмпатия: Через художественные детали (быт, костюмы, этикет) человек начинает понимать дух и логику ушедших эпох лучше, чем по учебникам.$$),
  (620, $$Понимание мировых культур: Литература знакомит с менталитетом, традициями и философией других народов, избавляя от местечкового провинциализма.$$),
  (621, $$Культурный код: Чтение классики дает ключ к пониманию сотен отсылок, цитат, мемов и метафор в современном кино, искусстве и медиа.$$),
  (622, $$Формирование ценностей: Книги ставят перед читателем фундаментальные этические вопросы о добре, зле, долге, свободе и предательстве.$$),
  (623, $$Политическая грамотность: Антиутопии и исторические хроники наглядно показывают механизмы работы пропаганды, власти и тоталитарных систем.$$),
  (624, $$Избавление от предрассудков: Литература развенчивает расовые, гендерные и социальные стереотипы, показывая ценность каждой отдельной личности.$$),
  (625, $$Философский склад ума: Книги приучают смотреть на жизненные неурядицы глобально, в масштабе вечности, снижая бытовую суету.$$),
  (626, $$Религиоведческая эрудиция: Сюжеты классики часто пронизаны библейскими, буддийскими или мифологическими мотивами, расширяя духовный кругозор.$$),
  (627, $$Гражданская осознанность: Литература пробуждает чувство личной ответственности за происходящее в обществе и стране.$$),
  (628, $$Глобальное видение мира: Чтение объединяет времена и пространства: человек начинает ощущать себя частью единой человеческой цивилизации.$$),
  (629, $$Стратегическое планирование: Масштабные романы-эпопеи учат видеть развитие процессов в долгосрочной перспективе.$$),
  (630, $$Навык нетворкинга: Эрудиция и начитанность делают человека магнетическим собеседником, способным поддержать разговор в любых кругах.$$),
  (631, $$Стрессоустойчивость на работе: Книги показывают примеры того, как великие лидеры справлялись с катастрофическими кризисами и крахом.$$),
  (632, $$Тайм-менеджмент: Привычка ежедневно выделять время на чтение развивает жесткую самодисциплину, которая переносится на рабочие задачи.$$),
  (633, $$Написание текстов (Copywriting): Любой начитанный человек пишет отчеты, деловые письма и посты в разы качественнее, убедительнее и быстрее.$$),
  (634, $$Уверенность в себе: Человек, обладающий глубоким багажом знаний из книг, чувствует себя психологически устойчиво на переговорах и собеседованиях.$$),
  (635, $$Умение делегировать: Понимание психологии типов (благодаря литературе) помогает руководителю правильно распределять задачи в команде.$$),
  (636, $$Отложенное вознаграждение: Чтение массивных трудов приучает мозг долго работать ради качественного финала, что важно в стартапах и долгих проектах.$$),
  (637, $$Адаптивность к изменениям: Литература учит, что мир изменчив, помогая легче переносить реструктуризации, смену профессий и кризисы на рынке.$$),
  (638, $$Харизма лидера: Умение рассказывать истории (сторителлинг), перенятое у великих авторов, зажигает людей и ведет их за собой.$$),
  (639, $$Библиотерапия: Чтение книг о людях со схожими психологическими проблемами помогает осознать и проработать собственные комплексы.$$),
  (640, $$Эффект «Я не один»: Книга дарит утешение, доказывая, что твои самые потаенные страхи, боли и сомнения уже переживал кто-то другой сто лет назад.$$),
  (641, $$Снижение уровня тревоги: Погружение в качественный текст полностью переключает мозг, останавливая бесконечную мысленную жвачку о бытовых проблемах.$$),
  (642, $$Принятие своей уникальности: Литература воспевает странных, эксцентричных и сложных героев, помогая читателю принять свою непохожесть на других.$$),
  (643, $$Саморефлексия: Книги задают неудобные вопросы, заставляя анализировать свои поступки, мотивы и честно смотреть в зеркало своей души.$$),
  (644, $$Обретение внутренних опор: Моральные ориентиры книжных героев становятся для человека внутренним компасом в моменты экзистенциального кризиса.$$),
  (645, $$Лечение одиночества: Книга — идеальный, никогда не предающий собеседник, который заменяет дефицит качественного общения в реальности.$$),
  (646, $$Преодоление страха неудач: Жизнеописания персонажей, прошедших через череду провалов к триумфу, мотивируют не опускать руки после первых ошибок.$$),
  (647, $$Катарсис (Очищение): Переживание сильных слез или смеха над страницами книги освобождает психику от подавленных заблокированных эмоций.$$),
  (648, $$Осознанность (Mindfulness): Чтение бумажной книги требует уединения и тишины, возвращая человека в момент «здесь и сейчас».$$),
  (649, $$Раннее интеллектуальное превосходство: Дети, которым много читали вслух, опережают сверстников в развитии речи и логики к началу школы.$$),
  (650, $$Формирование границ «добра и зла»: Сказки и детские повести закладывают базовый моральный фундамент до того, как ребенок столкнется с суровостью жизни.$$),
  (651, $$Усидчивость и самоконтроль: Книга приучает гиперактивного ребенка сидеть на месте и концентрироваться, развивая лобные доли мозга.$$),
  (652, $$Безопасное познание мира: Через книги ребенок узнает об опасностях (предательстве, обмане, смерти) в мягкой, защищенной форме.$$),
  (653, $$Укрепление связи с родителями: Совместное вечернее чтение формирует у ребенка чувство абсолютной безопасности и глубокой эмоциональной привязанности.$$),
  (654, $$Развитие школьной успеваемости: Любовь к чтению автоматически подтягивает оценки по всем предметам, так как ребенок быстрее усваивает любые текстовые задания.$$),
  (655, $$Профилактика интернет-зависимости: Ребенок, умеющий получать дофамин от чтения сюжетов, менее подвержен слепому залипанию в гаджетах.$$),
  (656, $$Формирование идеалов: Благородные детские персонажи (Мушкетеры, Питер Пэн, Гарри Поттер) становятся первыми ролевыми моделями для подражания.$$),
  (657, $$Развитие самостоятельности: Чтение приключенческой литературы вдохновляет детей на личные исследования, игры и активность на свежем воздухе.$$),
  (658, $$Эмоциональная стабильность: Детская литература учит справляться со страхами (боязнью темноты, одиночества) через метафорические победы над монстрами.$$),
  (659, $$Физическое омоложение мозга: Чтение заставляет мозг постоянно строить новые синапсы, сдвигая начало возрастного увядания разума на десятилетия.$$),
  (660, $$Снижение мышечного напряжения: Глубокое погружение в текст расслабляет мышцы лица, шеи и плеч эффективнее, чем массаж или алкоголь.$$),
  (661, $$Замедление пульса: Ритмичное чтение про себя выравнивает сердечный ритм, переводя организм в состояние глубокого физического покоя.$$),
  (662, $$Нормализация дыхания: Увлеченный читатель начинает дышать глубже и реже, что улучшает вентиляцию легких и насыщение тканей кислородом.$$),
  (663, $$Тренировка глазных мышц: Движение зрачка по строкам слева направо (и обратно) является естественной мягкой гимнастикой для цилиарной мышцы глаза.$$),
  (664, $$Подавление гормонов стресса: Чтение блокирует выброс адреналина и кортизола, спасая сосуды от спазмов и защищая сердце.$$),
  (665, $$Укрепление иммунитета: За счет снижения общего уровня психосоматического стресса организм эффективнее борется с вирусами и инфекциями.$$),
  (666, $$Улучшение качества сна: Чтение печатной страницы перед сном расслабляет нервную систему, обеспечивая глубокую фазу сна без ночных кошмаров.$$),
  (667, $$Улучшение мелкой моторики и координации: Перелистывание страниц, удержание книги, работа с закладками поддерживают точность движений пальцев.$$),
  (668, $$Повышение общего тонуса жизни: Регулярный интеллектуальный дофамин от хороших книг держит человека в состоянии бодрости и когнитивного тонуса.$$),
  (669, $$Защита от стадного инстинкта: Начитанный человек имеет собственное мнение и критический фильтр, его невозможно увлечь слепой толпой или лозунгами.$$),
  (670, $$Внутренняя свобода: Книги показывают, что физические стены — ничто, если твой разум свободен и способен путешествовать сквозь века.$$),
  (671, $$Умение проживать одиночество: Читающему человеку никогда не бывает скучно наедине с собой, он самодостаточен и независим от внешних развлечений.$$),
  (672, $$Глубина личности: Литература превращает человека из плоского обывателя в сложную, многогранную личность с богатым внутренним ландшафтом.$$),
  (673, $$Уважение к своей истории: Книги помогают осознать свои корни, понять историю своей семьи и своего народа в контексте мировой истории.$$),
  (674, $$Смелость быть собой: Литературные примеры бунтарей и гениев учат отстаивать свои границы и не подстраиваться под чужие ожидания.$$),
  (675, $$Нескончаемый источник вдохновения: В любой момент кризиса или депрессии человек может открыть великую книгу и найти там силы жить дальше.$$),
  (676, $$Интеллектуальная автономия: Начитанность дает свободу выбирать себе авторитетов сознательно, а не принимать тех, кого навязывает мода или алгоритмы.$$),
  (677, $$Мудрость опыта веков: Читая, вы за одну жизнь проживаете тысячи чужих жизней, забирая себе их опыт, ошибки, победы и выводы.$$),
  (678, $$Создание лучшей версии себя: Каждый прочитанный шедевр оставляет след в структуре вашей личности, по кирпичику выстраивая человека мыслящего, чувствующего и созидающего.$$)
)
INSERT INTO "philology_facts" ("id", "text", "category", "characterEmotion", "updatedAt")
SELECT
  'lily-library-' || lpad(ordinal::text, 5, '0'),
  text,
  'LITERATURE',
  CASE ordinal % 3 WHEN 1 THEN 'THOUGHTFUL' WHEN 2 THEN 'SURPRISED' ELSE 'JOYFUL' END,
  CURRENT_TIMESTAMP
FROM supplied_facts;

-- Do not delete this content: pause every editorial card about Russia,
-- Russian authors, Russian-language vocabulary, the USSR, or Soviet history.
-- The Lily selector already requires isActive = true, so the change takes
-- effect immediately for new facts while remaining fully reversible.
UPDATE "philology_facts"
SET "isActive" = FALSE, "updatedAt" = CURRENT_TIMESTAMP
WHERE "isActive" = TRUE
  AND "text" ~* '(росси|русск|ссср|советск|большевик|петроград|кремл|сталин|пастернак|достоевск|толст|пушкин|гогол|лермонтов|чехов|есенин|маяковск|тургенев|некрасов|гумилев|ахматов|мандельштам|зощенко|салтыков|жуковск|грибоедов|булгаков|бунин|куприн|горьк|фет|фонвизин|тютчев|жданов|солженицын|стругацк|ильф|петров|набоков|чуковск|крылов|беляев|акунин|гайдар|блок|волошин|бендер|ппш|живаго|облонск|мюнхгаузен)';

